{"content": [{"type": "text", "text": "{
  "id": 124761,
  "name": "HasDerivAt",
  "source_text": "/-- `f` has the derivative `f'` at the point `x`.\n\nThat is, `f x' = f x + (x' - x) • f' + o(x' - x)` where `x'` converges to `x`.\n-/\ndef HasDerivAt (f : 𝕜 → F) (f' : F) (x : 𝕜) :=\n  HasDerivAtFilter f f' (𝓝 x ×ˢ pure x)\n"
}"}], "structured_content": {"result": {"id": 124761, "name": "HasDerivAt", "source_text": "/-- `f` has the derivative `f'` at the point `x`.

That is, `f x' = f x + (x' - x) • f' + o(x' - x)` where `x'` converges to `x`.
-/
def HasDerivAt (f : 𝕜 → F) (f' : F) (x : 𝕜) :=
  HasDerivAtFilter f f' (𝓝 x ×ˢ pure x)
"}}}

{"content": [{"type": "text", "text": "{
  "id": 134739,
  "name": "Orientation.areaForm",
  "source_text": "/-- An antisymmetric bilinear form on an oriented real inner product space of dimension 2 (usual\nnotation `ω`). When evaluated on two vectors, it gives the oriented area of the parallelogram they\nspan. -/\nirreducible_def areaForm : E →ₗ[ℝ] E →ₗ[ℝ] ℝ := by\n  let z : E [⋀^Fin 0]→ₗ[ℝ] ℝ ≃ₗ[ℝ] ℝ :=\n    AlternatingMap.constLinearEquivOfIsEmpty.symm\n  let y : E [⋀^Fin 1]→ₗ[ℝ] ℝ →ₗ[ℝ] E →ₗ[ℝ] ℝ :=\n    LinearMap.llcomp ℝ E (E [⋀^Fin 0]→ₗ[ℝ] ℝ) ℝ z ∘ₗ AlternatingMap.curryLeftLinearMap\n  exact y ∘ₗ AlternatingMap.curryLeftLinearMap o.volumeForm\n"
}"}], "structured_content": {"result": {"id": 134739, "name": "Orientation.areaForm", "source_text": "/-- An antisymmetric bilinear form on an oriented real inner product space of dimension 2 (usual
notation `ω`). When evaluated on two vectors, it gives the oriented area of the parallelogram they
span. -/
irreducible_def areaForm : E →ₗ[ℝ] E →ₗ[ℝ] ℝ := by
  let z : E [⋀^Fin 0]→ₗ[ℝ] ℝ ≃ₗ[ℝ] ℝ :=
    AlternatingMap.constLinearEquivOfIsEmpty.symm
  let y : E [⋀^Fin 1]→ₗ[ℝ] ℝ →ₗ[ℝ] E →ₗ[ℝ] ℝ :=
    LinearMap.llcomp ℝ E (E [⋀^Fin 0]→ₗ[ℝ] ℝ) ℝ z ∘ₗ AlternatingMap.curryLeftLinearMap
  exact y ∘ₗ AlternatingMap.curryLeftLinearMap o.volumeForm
"}}}

